import{_ as d,o as a,c as e,ag as i}from"./chunks/framework.Ca42NP5A.js";const s="/docs/assets/view.CGidDupY.png",n="/docs/assets/view-top-design.D14UME-X.png",u=JSON.parse('{"title":"AM_CAN_Bridge контроллер коммутиации и инжекции для шины данных","description":"","frontmatter":{},"headers":[],"relativePath":"am_can_to_can_bridge/index.md","filePath":"am_can_to_can_bridge/README.md"}'),r={name:"am_can_to_can_bridge/index.md"};function l(o,t,h,c,p,g){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="am-can-bridge-контроллер-коммутиации-и-инжекции-для-шины-данных" tabindex="-1">AM_CAN_Bridge контроллер коммутиации и инжекции для шины данных <a class="header-anchor" href="#am-can-bridge-контроллер-коммутиации-и-инжекции-для-шины-данных" aria-label="Permalink to &quot;AM_CAN_Bridge контроллер коммутиации и инжекции для шины данных&quot;">​</a></h1><ul><li>разрывает входную CAN-линию <code>CAN0 IN</code> двумя последовательно установленными нормально-замкнутыми релейными каскадами;</li><li>принимает <code>CAN0 IN</code> контроллером <strong>TCAN4550-Q1</strong> и передаёт кадры в MCU по SPI;</li><li>формирует отдельный выход <code>CAN0 OUT</code> через встроенный в базовую плату трансивер <strong>TJA1042</strong>;</li><li>предоставляет независимую линию <code>CAN2</code> через второй TJA1042;</li><li>предоставляет 10/100BASE-TX Ethernet через PHY <strong>LAN8742A</strong> и разъём M8;</li><li>принимает основное питание через XT30, M8 или M12 и резервное/сервисное питание через USB-C;</li><li>измеряет входное напряжение и сообщает MCU о наличии основных шин питания;</li><li>управляет вибромотором через DRV2603.</li></ul><p>Функция моста, фильтрация и пересылка CAN-кадров выполняются прошивкой. При выключенной плате или до инициализации GPIO релейные каскады соединяют <code>CAN0 IN</code> только со входом TCAN4550. Аппаратного bypass между <code>CAN0 IN</code> и <code>CAN0 OUT</code> нет: без работающей прошивки кадры между сегментами не передаются.</p><p><img src="'+s+`" alt="Габариты"></p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Узел</th><th>Реализация</th><th>Примечание</th></tr></thead><tbody><tr><td>MCU</td><td>микроконтроллер</td><td>точная ревизия модуля не указана</td></tr><tr><td>CAN0, вход</td><td>TCAN4550-Q1, CAN FD, связь с MCU по SPI6</td><td>после двух нормально-замкнутых релейных каскадов</td></tr><tr><td>CAN0, выход</td><td>FDCAN1 MCU + TJA1042</td><td>D65 <code>CAN H/L OUT</code>, параллельно <code>CAN1_C</code></td></tr><tr><td>CAN2</td><td>FDCAN2 MCU + TJA1042</td><td>выведен на M8, M12 и <code>CAN2_C</code></td></tr><tr><td>Разрыв CAN0</td><td>два независимых последовательных каскада</td><td>варианты IM13GR, G6K-2F или 2×LCB710S на каскад; устанавливается только один вариант</td></tr><tr><td>Ethernet</td><td>LAN8742A, RMII, 10/100BASE-TX</td><td>только на M8; PHY address = 1 при R56 = 10 kΩ</td></tr><tr><td>USB</td><td>USB-C, USB 2.0 Full Speed</td><td>sink/UFP, CC1/CC2 по 5.1 kΩ; USB также питает системную шину 5 V</td></tr><tr><td>Основное питание</td><td>внешний модуль DCDCLMR16030, выход <code>5V_B</code></td><td>входы XT30, M8 и M12 электрически объединены</td></tr><tr><td>Резервирование 5 V</td><td>диодное OR <code>5V_B</code> и USB <code>5V_C</code></td><td>D1 PMEG2020CP</td></tr><tr><td>Контроль Vin</td><td>делитель 180 kΩ / 10 kΩ</td><td><code>ADC_V_IN = Vin / 19</code> на PA3</td></tr></tbody></table><h2 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h2><h3 id="connectors" tabindex="-1"><strong>Connectors</strong> <a class="header-anchor" href="#connectors" aria-label="Permalink to &quot;**Connectors**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Обозначение</th><th>Тип по схеме/чертежу</th><th>Назначение</th><th>Замечания</th></tr></thead><tbody><tr><td>XT30PW-M</td><td>2-контактный силовой</td><td>основное питание <code>Vin_in</code>, GND</td><td>полярность проверить по маркировке PCB перед подключением</td></tr><tr><td>M8</td><td>8 контактов + корпус</td><td>Ethernet, CAN2, питание</td><td>механический чертёж и схема расходятся по обозначению TX/RX и полярности пары B; см. E-04/E-05</td></tr><tr><td>M12</td><td>5 контактов</td><td>CAN2, питание, 2×GND</td><td><code>Vin_in</code> напрямую объединён с XT30 и M8</td></tr><tr><td>D65</td><td>6 контактов</td><td>разрываемая CAN0-линия: IN/OUT</td><td>контакт 1 не подключён</td></tr><tr><td>CAN1_C</td><td>JST-GH SM04B-GHS</td><td>параллельный доступ к CAN0 OUT</td><td>контакты 1 и 4 NC; экранные лапки на GND</td></tr><tr><td>CAN2_C</td><td>JST-GH SM04B-GHS</td><td>параллельный доступ к CAN2</td><td>контакты 1 и 4 NC; экранные лапки на GND</td></tr><tr><td>USB-C</td><td>UJ31-CH-31N-SMT-TR</td><td>USB 2.0 FS и сервисное питание</td><td>нет отдельной ESD-защиты D+/D− на схеме</td></tr><tr><td>MOTOR</td><td>3 контакта</td><td>вибромотор</td><td>контакт 3 NC</td></tr></tbody></table><h3 id="m8" tabindex="-1">M8 <a class="header-anchor" href="#m8" aria-label="Permalink to &quot;M8&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Контакт</th><th>Сигнал по электрической схеме</th><th>Функция</th><th>Примечание</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>GND</td><td>питание/сигнальная земля</td><td>корпус M8 также соединён с GND</td></tr><tr><td style="text-align:right;">2</td><td><code>ETH-1A_N</code></td><td>Ethernet, пара A−</td><td>на механическом чертеже обозначен RX−</td></tr><tr><td style="text-align:right;">3</td><td><code>ETH-1A_P</code></td><td>Ethernet, пара A+</td><td>на механическом чертеже обозначен RX+</td></tr><tr><td style="text-align:right;">4</td><td>фактически пара B−</td><td>Ethernet, пара B−</td><td>на схеме возле разъёма подписан <code>ETH-1B_P</code>; см. E-04</td></tr><tr><td style="text-align:right;">5</td><td>фактически пара B+</td><td>Ethernet, пара B+</td><td>на схеме возле разъёма подписан <code>ETH-1B_N</code>; см. E-04</td></tr><tr><td style="text-align:right;">6</td><td><code>Vin_in</code></td><td>основное питание</td><td>объединён с XT30 и M12.4</td></tr><tr><td style="text-align:right;">7</td><td><code>CAN2_H</code></td><td>CAN2 high</td><td>без встроенной терминации 120 Ω</td></tr><tr><td style="text-align:right;">8</td><td><code>CAN2_L</code></td><td>CAN2 low</td><td>без встроенной терминации 120 Ω</td></tr><tr><td style="text-align:right;">P1, P2</td><td>GND</td><td>корпус/экран</td><td>отдельной chassis/PE-сети нет</td></tr></tbody></table><h3 id="m12" tabindex="-1">M12 <a class="header-anchor" href="#m12" aria-label="Permalink to &quot;M12&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Контакт</th><th>Сигнал</th><th>Функция</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>CAN2_L</code></td><td>CAN2 low</td></tr><tr><td style="text-align:right;">2</td><td><code>CAN2_H</code></td><td>CAN2 high</td></tr><tr><td style="text-align:right;">3</td><td>GND</td><td>земля</td></tr><tr><td style="text-align:right;">4</td><td><code>Vin_in</code></td><td>основное питание</td></tr><tr><td style="text-align:right;">5</td><td>GND</td><td>земля</td></tr></tbody></table><h3 id="d65" tabindex="-1">D65 <a class="header-anchor" href="#d65" aria-label="Permalink to &quot;D65&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Контакт</th><th>Сигнал</th><th>Функция</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>NC</td><td>не подключён</td></tr><tr><td style="text-align:right;">2</td><td><code>CAN0_H_OUT</code></td><td>выход CAN0 high после программного моста</td></tr><tr><td style="text-align:right;">3</td><td><code>CAN0_L_OUT</code></td><td>выход CAN0 low после программного моста</td></tr><tr><td style="text-align:right;">4</td><td>GND</td><td>сигнальная земля</td></tr><tr><td style="text-align:right;">5</td><td><code>CAN0_L_IN</code></td><td>вход CAN0 low до релейных каскадов</td></tr><tr><td style="text-align:right;">6</td><td><code>CAN0_H_IN</code></td><td>вход CAN0 high до релейных каскадов</td></tr></tbody></table><h3 id="can1-c-can2-c" tabindex="-1">CAN1_C / CAN2_C <a class="header-anchor" href="#can1-c-can2-c" aria-label="Permalink to &quot;CAN1_C / CAN2_C&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Контакт</th><th>CAN1_C</th><th>CAN2_C</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>NC</td><td>NC</td></tr><tr><td style="text-align:right;">2</td><td><code>CAN1_H</code> = <code>CAN0_H_OUT</code></td><td><code>CAN2_H</code></td></tr><tr><td style="text-align:right;">3</td><td><code>CAN1_L</code> = <code>CAN0_L_OUT</code></td><td><code>CAN2_L</code></td></tr><tr><td style="text-align:right;">4</td><td>NC</td><td>NC</td></tr><tr><td style="text-align:right;">SH1, SH2</td><td>GND</td><td>GND</td></tr></tbody></table><h3 id="usb-c" tabindex="-1">USB-C <a class="header-anchor" href="#usb-c" aria-label="Permalink to &quot;USB-C&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Контакты</th><th>Сигнал</th><th>Подключение</th></tr></thead><tbody><tr><td>A6/B6</td><td>D+</td><td>через 22 Ω к PA12 / USB_OTG_FS_DP</td></tr><tr><td>A7/B7</td><td>D−</td><td>через 22 Ω к PA11 / USB_OTG_FS_DM</td></tr><tr><td>A5, B5</td><td>CC1, CC2</td><td>по 5.1 kΩ на GND, устройство UFP/sink</td></tr><tr><td>A4/A9/B4/B9</td><td>VBUS</td><td><code>5V_C</code>, далее через D1 в системные 5 V</td></tr><tr><td>GND, shield</td><td>GND</td><td>экран соединён с логической землёй</td></tr></tbody></table><h2 id="functional-block-diagram" tabindex="-1">Functional Block Diagram <a class="header-anchor" href="#functional-block-diagram" aria-label="Permalink to &quot;Functional Block Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    VIN[&quot;Vin: XT30 / M8 / M12&quot;] --&gt; DCDC[&quot;DCDCLMR16030: 5V_B&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    USB[&quot;USB-C: 5V_C&quot;] --&gt; ORING[&quot;Schottky OR: system 5 V&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DCDC --&gt; ORING</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ORING --&gt; FMU[&quot;MCU&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D65IN[&quot;D65: CAN0 IN&quot;] --&gt; CUT[&quot;SSR1 + SSR2, normally closed&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CUT --&gt; TCAN[&quot;TCAN4550 CAN FD&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TCAN --&gt;|SPI6| FMU</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FMU --&gt;|FDCAN1 + TJA1042| D65OUT[&quot;D65: CAN0 OUT / CAN1_C&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FMU --&gt;|FDCAN2 + TJA1042| CAN2[&quot;CAN2: M8 / M12 / CAN2_C&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FMU --&gt;|RMII + LAN8742A| ETH[&quot;10/100BASE-TX: M8&quot;]</span></span></code></pre></div><h2 id="functional-description" tabindex="-1">Functional description <a class="header-anchor" href="#functional-description" aria-label="Permalink to &quot;Functional description&quot;">​</a></h2><h3 id="can0-bridge-and-isolation" tabindex="-1">CAN0 bridge and isolation <a class="header-anchor" href="#can0-bridge-and-isolation" aria-label="Permalink to &quot;CAN0 bridge and isolation&quot;">​</a></h3><p><code>CAN0 IN</code> и <code>CAN0 OUT</code> — разные CAN-сегменты. Электрического соединения между ними в штатной работе нет: кадр с входа принимает TCAN4550, после чего прошивка решает, пересылать ли его через FDCAN1/TJA1042 на выход. Релейные каскады разрывают только путь от D65 <code>CAN0 IN</code> к TCAN4550 и не отключают <code>CAN0 OUT</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">SSR1 EN</th><th style="text-align:right;">SSR2 EN</th><th>Физический путь D65 IN → TCAN4550</th><th>Состояние при старте</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>замкнут</td><td>штатное, задаётся pulldown 4.7 kΩ</td></tr><tr><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>разомкнут каскадом 1</td><td>отключён</td></tr><tr><td style="text-align:right;">0</td><td style="text-align:right;">1</td><td>разомкнут каскадом 2</td><td>отключён</td></tr><tr><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>разомкнут обоими каскадами</td><td>отключён с аппаратным резервированием контактов</td></tr></tbody></table><p>Два каскада дают резервирование разрыва только при независимом корректном управлении. Обратной связи о фактическом состоянии контактов нет.</p><h3 id="power-tree" tabindex="-1">Power tree <a class="header-anchor" href="#power-tree" aria-label="Permalink to &quot;Power tree&quot;">​</a></h3><ul><li><code>Vin_in</code> и <code>Vin</code> — одна сырая входная шина. XT30, M8.6 и M12.4 соединены параллельно.</li><li>Модуль DCDCLMR16030 постоянно разрешён от Vin и формирует <code>5V_B</code>.</li><li>USB-C формирует <code>5V_C</code>.</li><li>D1 объединяет <code>5V_B</code> и <code>5V_C</code> через два диода Шоттки в системную шину 5 V и препятствует обратному току между источниками.</li><li>Делитель R10/R13 формирует <code>ADC_V_IN = Vin / 19</code>; при опорном напряжении ADC 3.3 V теоретический диапазон составляет около 62.7 V, но допустимое напряжение всей платы существенно ниже из-за TCAN4550 и защитных компонентов.</li><li>Q2 и Q1 формируют активные-low сигналы наличия <code>5V_B</code> и <code>5V_C</code>.</li></ul><h2 id="application-scenarios" tabindex="-1">Application scenarios <a class="header-anchor" href="#application-scenarios" aria-label="Permalink to &quot;Application scenarios&quot;">​</a></h2><p>В общей архитектуре AM_CAN_Bridge устанавливается между группами штатных узлов D553/D551 либо D550/D554/D552 и остальной сетью станка. Таким образом образуются два независимых CAN-сегмента. Любой кадр, который должен пройти через устройство, принимается на одном сегменте и передаётся заново на другом; стрелки на схемах ниже показывают логический поток данных, а не направление электрического CAN-интерфейса.</p><h3 id="_1-программно-прозрачное-подключение-к-штатнои-can-сети" tabindex="-1">1. Программно-прозрачное подключение к штатной CAN-сети <a class="header-anchor" href="#_1-программно-прозрачное-подключение-к-штатнои-can-сети" aria-label="Permalink to &quot;1. Программно-прозрачное подключение к штатной CAN-сети&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>Плата включается в разрыв штатной CAN-линии и в нормальном режиме пересылает разрешённые кадры без изменения данных. Одновременно прошивка собирает статистику, метки времени и диагностические события.</td></tr><tr><td>Подключаемые элементы</td><td>Сегмент штатных узлов D55x → <code>CAN0 IN</code>; остальная сеть станка и D501 → <code>CAN0 OUT</code>; питание 24 V; при необходимости Ethernet/USB для диагностики. Конкретное направление IN/OUT проверить по жгуту и netlist сборки.</td></tr><tr><td>Результат применения</td><td>Получается управляемая точка наблюдения и фильтрации, через которую впоследствии можно вводить подмену и синтез трафика без изменения остальных ECU.</td></tr><tr><td>Если не применять</td><td>Штатные узлы остаются в одном домене арбитража; выборочно остановить, изменить или зарегистрировать их трафик без отдельного анализатора невозможно.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    STOCK[&quot;Штатные узлы D55x&quot;] --&gt; IN[&quot;CAN0 IN / TCAN4550&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    IN --&gt; FW[&quot;MCU: контроль и пересылка&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FW --&gt; OUT[&quot;CAN0 OUT / TJA1042&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    OUT --&gt; MACHINE[&quot;Остальная CAN-сеть станка&quot;]</span></span></code></pre></div><blockquote><p>Это программно-прозрачный, а не аппаратно-прозрачный мост. Отказ питания, зависание MCU или остановка пересылки разрывают обмен между сегментами.</p></blockquote><h3 id="_2-подмена-отдельных-can-пакетов" tabindex="-1">2. Подмена отдельных CAN-пакетов <a class="header-anchor" href="#_2-подмена-отдельных-can-пакетов" aria-label="Permalink to &quot;2. Подмена отдельных CAN-пакетов&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>Прошивка пропускает основной трафик без изменений, но для выбранных CAN ID подавляет исходный кадр и передаёт вместо него кадр с рассчитанным значением. Например, можно заменить отдельный статус или команду штатного узла D553/D551/D550/D554/D552.</td></tr><tr><td>Подключаемые элементы</td><td>Источник штатных кадров на одном CAN0-сегменте; потребители на втором сегменте; при необходимости внешний вычислитель по Ethernet, USB или CAN2, формирующий новое значение.</td></tr><tr><td>Результат применения</td><td>Потребители получают штатный набор сообщений, но выбранный параметр управляется системой автоматизации. Остальные ID продолжают проходить через мост.</td></tr><tr><td>Если не применять</td><td>Исходный кадр штатного ECU попадёт к потребителям без изменения либо для подмены потребуется отключать ECU и полностью эмулировать весь его трафик.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ECU[&quot;Штатный ECU&quot;] --&gt; RX[&quot;Приём CAN ID&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RX --&gt; RULE[&quot;Фильтр: пропустить или заменить&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AUTO[&quot;Данные автоматизации&quot;] --&gt; RULE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    RULE --&gt; CONSUMER[&quot;Штатные потребители&quot;]</span></span></code></pre></div><p>Для заменяемого ID прошивка должна воспроизводить исходные DLC, период, порядок байтов, rolling counter, checksum/CRC и допустимый jitter. Нельзя сначала пропустить исходный кадр, а затем отправить замену: потребитель может обработать оба значения, а при одинаковом ID возникнет конкуренция источников.</p><h3 id="_3-синтез-трафика-виртуального-can-узла" tabindex="-1">3. Синтез трафика виртуального CAN-узла <a class="header-anchor" href="#_3-синтез-трафика-виртуального-can-узла" aria-label="Permalink to &quot;3. Синтез трафика виртуального CAN-узла&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>Отключённый или физически отсутствующий штатный узел заменяется программной моделью. AM_CAN_Bridge периодически формирует его heartbeat, статусы и ответы, а команды для виртуального узла преобразует в действия системы автоматизации.</td></tr><tr><td>Подключаемые элементы</td><td>AM_CAN_Bridge к сегменту потребителей; источник состояния по Ethernet/CAN2/USB; при необходимости релейное отключение входного сегмента, чтобы исключить сообщения штатного узла.</td></tr><tr><td>Результат применения</td><td>Сеть продолжает видеть ожидаемый ECU, а его функции могут быть реализованы автономным контроллером или внешним вычислителем.</td></tr><tr><td>Если не применять</td><td>Потребители фиксируют timeout/missing node, переходят в ошибку или запрещают функцию; простое отключение штатного ECU нарушает связанные диагностические процедуры.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    STATE[&quot;Состояние системы автоматизации&quot;] --&gt; MODEL[&quot;Модель виртуального ECU&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    MODEL --&gt; SCHED[&quot;Планировщик CAN-сообщений&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SCHED --&gt; BUS[&quot;Штатная CAN-сеть&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BUS --&gt; CMD[&quot;Команды и диагностика к модели&quot;]</span></span></code></pre></div><p>Синтезировать сообщения можно только после записи реального трафика и определения состояний запуска, периодов, counters, CRC и timeout. Эмуляция не должна использоваться вместо аппаратного аварийного контура или подтверждения физического состояния механизма.</p><h3 id="_4-преобразование-цифровых-данных-датчиков-в-единую-can-шину" tabindex="-1">4. Преобразование цифровых данных датчиков в единую CAN-шину <a class="header-anchor" href="#_4-преобразование-цифровых-данных-датчиков-в-единую-can-шину" aria-label="Permalink to &quot;4. Преобразование цифровых данных датчиков в единую CAN-шину&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>Цифровые данные дополнительных датчиков нормализуются, масштабируются и публикуются в общей CAN-сети в виде единого набора сообщений. Примеры по общей схеме: датчик оборотов/RFID, vibration node, GNSS/компас либо диагностический датчик с Ethernet/USB/CAN-выходом.</td></tr><tr><td>Подключаемые элементы</td><td>Цифровой датчик или внешний acquisition node; Ethernet, USB либо CAN2 платы; целевой CAN0-сегмент. Для дискретных PNP/NPN, герконов, энкодеров и импульсных входов требуется отдельный I/O-модуль — напрямую к CAN-разъёму они не подключаются.</td></tr><tr><td>Результат применения</td><td>Контроллеры станка и системы автоматизации получают данные разных датчиков в одном формате и с едиными правилами диагностики качества/актуальности.</td></tr><tr><td>Если не применять</td><td>Для каждого датчика требуется отдельный драйвер и физический интерфейс на каждом потребителе; усложняются кабельная сеть, синхронизация и диагностика.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SENSOR[&quot;Цифровой датчик&quot;] --&gt; ACQ[&quot;Датчик или I/O-контроллер&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ACQ --&gt;|&quot;Ethernet / USB / CAN2&quot;| BRIDGE[&quot;AM_CAN_Bridge&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BRIDGE --&gt;|&quot;Нормализованные CAN ID&quot;| CAN[&quot;Единая CAN-шина&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CAN --&gt; USERS[&quot;D501 и контроллеры&quot;]</span></span></code></pre></div><p>В каждом сообщении желательно передавать признак validity, возраст данных или счётчик обновлений. При timeout датчика мост должен публиковать заранее определённое invalid/safe-состояние, а не последнее значение бесконечно.</p><h3 id="_5-программная-коммутация-цифровых-интерфеисов" tabindex="-1">5. Программная коммутация цифровых интерфейсов <a class="header-anchor" href="#_5-программная-коммутация-цифровых-интерфеисов" aria-label="Permalink to &quot;5. Программная коммутация цифровых интерфейсов&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>MCU маршрутизирует команды и телеметрию между CAN0 IN, CAN0 OUT, CAN2, Ethernet и USB. Например, команды вычислителя поступают по Ethernet, преобразуются в разрешённые CAN-сообщения, а ответы ECU зеркалируются обратно в Ethernet-канал.</td></tr><tr><td>Подключаемые элементы</td><td>Вычислительный модуль или АСУ БВР по Ethernet; сервисный компьютер по USB; штатная сеть через CAN0; дополнительная сеть через CAN2.</td></tr><tr><td>Результат применения</td><td>Одна плата выполняет роль протокольного шлюза, маршрутизатора и точки диагностики; доступ каждого интерфейса можно ограничить whitelist и режимом работы.</td></tr><tr><td>Если не применять</td><td>Потребуются отдельные USB-CAN/Ethernet-CAN шлюзы, дополнительные соединения и согласование нескольких независимых конфигураций.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    HOST[&quot;Вычислитель / АСУ по Ethernet&quot;] --&gt; ROUTER[&quot;MCU: маршрутизация&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SERVICE[&quot;Сервисный ПК по USB&quot;] --&gt; ROUTER</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ROUTER --&gt; CAN0[&quot;CAN0 IN / OUT&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ROUTER --&gt; CAN2[&quot;Дополнительная CAN2&quot;]</span></span></code></pre></div><p>Это логическая коммутация и преобразование протоколов. Плата не содержит универсального физического коммутатора RS-232/RS-485/LIN и не может подключать такие линии без внешнего трансивера.</p><h3 id="_6-фильтрация-ошибочного-трафика-и-безопасное-замещение" tabindex="-1">6. Фильтрация ошибочного трафика и безопасное замещение <a class="header-anchor" href="#_6-фильтрация-ошибочного-трафика-и-безопасное-замещение" aria-label="Permalink to &quot;6. Фильтрация ошибочного трафика и безопасное замещение&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Пункт</th><th>Описание</th></tr></thead><tbody><tr><td>Сценарий</td><td>Мост применяет whitelist CAN ID, проверку диапазонов, частоты, counter/CRC и состояния машины. Недопустимая команда блокируется либо заменяется заранее определённым безопасным значением. При необходимости CAN0 IN отключается от TCAN4550 двумя релейными каскадами.</td></tr><tr><td>Подключаемые элементы</td><td>Штатный или автономный источник команд; AM_CAN_Bridge между ним и исполнительным сегментом; независимые hardwired цепи E-stop/fire suppression остаются отдельными.</td></tr><tr><td>Результат применения</td><td>Ошибочный или скомпрометированный источник не получает неограниченного доступа ко всей CAN-сети; события блокировки журналируются.</td></tr><tr><td>Если не применять</td><td>Некорректные команды, flood и повреждённые данные распространяются на потребителей без локального контроля.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SOURCE[&quot;Источник команд&quot;] --&gt; CHECK[&quot;ID + rate + counter + limits&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CHECK --&gt;|&quot;Разрешено&quot;| TARGET[&quot;Исполнительный CAN-сегмент&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CHECK --&gt;|&quot;Запрещено&quot;| SAFE[&quot;Drop / safe substitute / isolate&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SAFE --&gt; LOG[&quot;Журнал события&quot;]</span></span></code></pre></div><p>Программная фильтрация не является safety-функцией без отдельного анализа отказов. Аварийный останов и снятие энергии с исполнительных механизмов должны оставаться независимыми аппаратными цепями.</p><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h2><p><img src="`+n+`" alt="Габариты"></p><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение / статус</th></tr></thead><tbody><tr><td>Основное питание</td><td>nominal 24 VDC; рекомендуемый рабочий диапазон 18…24 VDC до валидации</td></tr><tr><td>Сервисное питание</td><td>USB VBUS 5 V</td></tr><tr><td>Ethernet</td><td>10/100BASE-TX, RMII</td></tr><tr><td>CAN</td><td>2× FDCAN через TJA1042; 1× CAN FD через TCAN4550-Q1</td></tr><tr><td>Терминация CAN</td><td>отсутствует на схеме; требуется внешняя топология с двумя 120 Ω на концах шины</td></tr><tr><td>SPI TCAN4550</td><td>до 18 MHz по спецификации компонента</td></tr><tr><td>Температура платы</td><td>не квалифицирована; определяется наименее стойким установленным компонентом и модулями</td></tr><tr><td>Выходная мощность 5 V</td><td>не установлена: требуется тепловой расчёт модуля, D1, дорожек и разъёмов</td></tr></tbody></table><h3 id="mechanical" tabindex="-1"><strong>Mechanical</strong> <a class="header-anchor" href="#mechanical" aria-label="Permalink to &quot;**Mechanical**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th style="text-align:right;">Значение</th></tr></thead><tbody><tr><td>Размер PCB</td><td style="text-align:right;">72.1 × 77.1 mm</td></tr><tr><td>Толщина PCB</td><td style="text-align:right;">1.6 mm</td></tr><tr><td>Сетка центров крепёжных отверстий</td><td style="text-align:right;">64.8 × 69.8 mm</td></tr><tr><td>Количество крепёжных отверстий</td><td style="text-align:right;">4</td></tr><tr><td>Диаметр отверстий</td><td style="text-align:right;">TBD — на предоставленном чертеже не указан</td></tr><tr><td>Максимальная высота сборки</td><td style="text-align:right;">TBD</td></tr><tr><td>Масса</td><td style="text-align:right;">TBD</td></tr><tr><td>Количество слоёв / медь / stack-up</td><td style="text-align:right;">TBD</td></tr><tr><td>Покрытие контактов PCB</td><td style="text-align:right;">TBD</td></tr><tr><td>Конформное покрытие (лак)</td><td style="text-align:right;">не задано</td></tr></tbody></table><h3 id="absolute-maximum-ratings" tabindex="-1">Absolute Maximum Ratings <a class="header-anchor" href="#absolute-maximum-ratings" aria-label="Permalink to &quot;Absolute Maximum Ratings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th style="text-align:right;">Предел</th><th>Основание / ограничение</th></tr></thead><tbody><tr><td><code>Vin</code> положительное</td><td style="text-align:right;">42 V max</td><td>absolute maximum VSUP TCAN4550-Q1; рабочий предел ниже</td></tr><tr><td><code>Vin</code> отрицательное</td><td style="text-align:right;">не допускается</td><td>входной защиты от переполюсовки на carrier-плате не показано</td></tr><tr><td>TCAN4550 VIO</td><td style="text-align:right;">3.135…5.25 V</td><td>диапазон питания интерфейсной логики компонента</td></tr><tr><td>TCAN4550 CANH/CANL</td><td style="text-align:right;">±58 V</td><td>абсолютный предел выводов трансивера, не предел разъёма или всей платы</td></tr><tr><td>MCU analog inputs</td><td style="text-align:right;">не более допустимого для MCU/STM32</td><td>PC3_C сейчас подключён к 5 V и требует исправления</td></tr></tbody></table><h3 id="recommended-operating-conditions" tabindex="-1">Recommended operating conditions <a class="header-anchor" href="#recommended-operating-conditions" aria-label="Permalink to &quot;Recommended operating conditions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Рекомендация</th></tr></thead><tbody><tr><td>Основное питание</td><td>24 VDC nominal, 18…24 VDC на текущей ревизии</td></tr><tr><td>Верхний рабочий предел Vin</td><td>не более 30 V по recommended VSUP TCAN4550-Q1; дополнительно учесть SMAJ24A и DCDC-модуль</td></tr><tr><td>Внешняя защита питания</td><td>предохранитель/ограничитель тока, защита от переполюсовки и импульсов по требованиям системы</td></tr><tr><td>USB</td><td>стандартный источник 5 V USB; не использовать как доказанный источник полной мощности платы без расчёта</td></tr><tr><td>CAN</td><td>витая пара 120 Ω; две терминальные нагрузки 120 Ω только на физических концах магистрали</td></tr><tr><td>Корпус</td><td>закрытый, с разгрузкой кабелей; для тяжёлой среды — с согласованным conformal coating</td></tr></tbody></table><h3 id="recommended-mechanical-mounting" tabindex="-1"><strong>Recommended mechanical mounting</strong> <a class="header-anchor" href="#recommended-mechanical-mounting" aria-label="Permalink to &quot;**Recommended mechanical mounting**&quot;">​</a></h3><ul><li>Использовать четыре стойки по сетке 64.8 × 69.8 mm; диаметр крепежа выбрать только после получения исходного fab drawing.</li><li>Исключить изгиб PCB при подключении M8/M12/XT30; усилие кабеля передавать на корпус, а не на пайку разъёма.</li><li>Обеспечить электрические зазоры под платой и над высокими компонентами модулей; полная 3D-высота сборки пока не определена.</li><li>Не использовать экранные выводы разъёмов как силовое PE-соединение без отдельного EMC-анализа.</li><li>Для вибрационной среды предусмотреть фиксацию припаиваемых модулей и тяжёлых реле, conformal coating и испытание сборки.</li></ul><h3 id="connection-example-diagram" tabindex="-1"><strong>Connection example diagram</strong> <a class="header-anchor" href="#connection-example-diagram" aria-label="Permalink to &quot;**Connection example diagram**&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PSU[&quot;24 VDC supply&quot;] --&gt;|&quot;fuse + protected cable&quot;| PWR[&quot;XT30 or M8 or M12&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SENSOR[&quot;Upstream CAN segment&quot;] --&gt;|&quot;CAN H/L + GND&quot;| D65IN[&quot;D65 CAN0 IN&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D65OUT[&quot;D65 CAN0 OUT&quot;] --&gt;|&quot;CAN H/L + GND&quot;| DOWN[&quot;Downstream CAN segment&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    HOST[&quot;Ethernet host or switch&quot;] --&gt;|&quot;2 twisted pairs&quot;| M8[&quot;M8 Ethernet&quot;]</span></span></code></pre></div><p>Не подавать питание одновременно через XT30, M8 и M12 от разных источников: эти контакты соединены напрямую и не имеют ORing-развязки.</p><h3 id="power-supply-recommendations" tabindex="-1">Power Supply Recommendations <a class="header-anchor" href="#power-supply-recommendations" aria-label="Permalink to &quot;Power Supply Recommendations&quot;">​</a></h3><ul><li>Предпочтительный источник: стабилизированный 24 VDC с отдельным предохранителем или электронным ограничением тока возле источника.</li><li>Добавить системную защиту от переполюсовки и импульсов, соответствующую реальному кабелю и стандартам машины.</li><li>Проверить, что установленные SMAJ24A не переходят в длительное лавинное состояние при максимальном напряжении источника.</li><li>Не рассчитывать на заявленные для микросхемы DCDC 3 A как на доступный ток платы: лимитируют модуль, D1, разъёмы, дорожки и теплоотвод.</li><li>Если питание приходит через USB, не подключать одновременно внешнюю шину 5 V напрямую; допустима только предусмотренная схемой подача Vin и/или USB VBUS.</li></ul>`,70)])])}const E=d(r,[["render",l]]);export{u as __pageData,E as default};
